export type { SvgElementProps, SvgRootProps, SvgStyle, SvgValue } from './svg-utils.js';

import type { Snippet } from 'svelte';

export type SvgValue = string | number | boolean | null | undefined;
export type SvgStyle = Record<string, SvgValue>;

/** Common static SVG props accepted by pdfcn's shape primitives. */
export interface SvgElementProps {
	children?: Snippet;
	style?: SvgStyle;
	class?: string;
	className?: string;
	[attribute: string]: unknown;
}

export interface SvgRootProps extends SvgElementProps {
	width?: number;
	height?: number;
	viewBox?: string;
	href?: string;
	alt?: string;
	content?: string;
}

const SVG_ATTRIBUTE_NAMES: Record<string, string> = {
	className: 'class',
	dominantBaseline: 'dominant-baseline',
	fillOpacity: 'fill-opacity',
	fillRule: 'fill-rule',
	fontFamily: 'font-family',
	fontSize: 'font-size',
	fontStyle: 'font-style',
	fontWeight: 'font-weight',
	letterSpacing: 'letter-spacing',
	markerEnd: 'marker-end',
	markerMid: 'marker-mid',
	markerStart: 'marker-start',
	strokeDasharray: 'stroke-dasharray',
	strokeDashoffset: 'stroke-dashoffset',
	strokeLinecap: 'stroke-linecap',
	strokeLinejoin: 'stroke-linejoin',
	strokeMiterlimit: 'stroke-miterlimit',
	strokeOpacity: 'stroke-opacity',
	strokeWidth: 'stroke-width',
	textAnchor: 'text-anchor'
};

/**
 * Normalizes React-style SVG aliases and flattens presentation styles into
 * attributes, matching pdfcn's Forme React helper.
 */
export const normalizeFormeSvgAttributes = (
	props: SvgElementProps
): Record<string, SvgValue> => {
	const normalized: Record<string, SvgValue> = {};

	for (const [name, value] of Object.entries(props)) {
		if (value === undefined || name === 'children') continue;

		if (name === 'style' && value && typeof value === 'object') {
			for (const [styleName, styleValue] of Object.entries(value)) {
				if (styleValue !== undefined) {
					normalized[SVG_ATTRIBUTE_NAMES[styleName] ?? styleName] = styleValue;
				}
			}
			continue;
		}

		if (typeof value !== 'function') {
			normalized[SVG_ATTRIBUTE_NAMES[name] ?? name] = value as SvgValue;
		}
	}

	return normalized;
};

/** Removes Svelte's hydration boundary comments from captured SVG markup. */
export const cleanCapturedSvg = (markup: string): string =>
	markup.replace(/<!--[\s\S]*?-->/g, '');

import { getContext, setContext } from 'svelte';

import { professionalTheme } from '$lib/themes/professional.js';
import type { PdfcnTheme } from '$lib/types/pdf-themes.js';

const PDFCN_THEME_KEY = Symbol('pdfcn-theme');

/**
 * Provides a theme to all pdfcn-svelte components below this point in the
 * component tree. Call once during component initialisation (the
 * `PdfcnThemeProvider` component does this for you).
 */
export function providePdfcnTheme(
	theme: PdfcnTheme = professionalTheme
): PdfcnTheme {
	setContext(PDFCN_THEME_KEY, theme);
	return theme;
}

/**
 * Reads the closest provided theme, falling back to the professional preset.
 */
export function usePdfcnTheme(): PdfcnTheme {
	return getContext<PdfcnTheme | undefined>(PDFCN_THEME_KEY) ?? professionalTheme;
}

